#pragma once

#include "swgui.h"
#include "swguicontrol.h"

class CSWGuiLevelUpCharGen;
class CSWCCreature;

class CSWGuiControl;
struct CSWGuiExtent;
class CSWGuiManager;
class CExoString;

// Shared panel of the level-up screen: five pages (abilities, skills, feats, powers, summary), each
// with its own title label and tab button. The category pages are separate panels owned by
// CSWGuiLevelUpCharGen; each one points back here through m_pCharGenPanel.
class CSWGuiLevelUpPanel : public CSWGuiPanel {
public:
    // <VTABLE-GEN: binary ground truth (_ZTV) — components regenerated by tools/hoist_headers.py -->
    virtual ~CSWGuiLevelUpPanel();                     // slots 0-1 (D2+D0)
    virtual void HandleInputEvent(int type, int val);
    virtual void OnPanelAdded();
    // </VTABLE-GEN>

    void ClearPowers();
    void ClearAbilities();
    void ClearSkills();
    void ClearFeats();
    void NewAbilityScores(int nStr, int nCha, int nInt, int nWis, int nCon, int nDex, int nExtra);
    void PlayGame();
    void OnSelectAcceptButton(CSWGuiControl* pControl);

    // The four category buttons. Each allocates its own sub-panel, gives it the shared
    // `bg_replacement` border, and stores `this` into that panel's back-pointer.
    void OnSelectAbilitiesButton(CSWGuiControl* pControl);
    void OnSelectSkillsButton(CSWGuiControl* pControl);
    void OnSelectFeatsButton(CSWGuiControl* pControl);
    void OnSelectPowersButton(CSWGuiControl* pControl);
    // Not a category button: collects the level's granted powers into the shared skill info box.
    // `pControl` is unused.
#if !KOTOR1
    void ShowGrantedPowers(CSWGuiControl* pControl);
#endif
    // Callbacks the pages give their owning page.
    void CancelledByChild();
    void AbilitySelectionCompleted();
    void SkillSelectionCompleted();
    void PowersSelectionCompleted();
    void FeatSelectionCompleted();
    void OnCancelPressed(CSWGuiControl* pControl);
    // Re-evaluates which of the sub-pages should be live.
    void ChangeState(int nState);
    // Only reached with `m_nInputClass != 0`.
    void SetCanCancel(int bCanCancel);

    CSWGuiLevelUpPanel(CSWGuiManager* pGuiManager, unsigned long long oid);

    CSWCCreature*         m_pCreature;
    CSWGuiLevelUpCharGen* m_pCharGenPanel;
#if KOTOR1
    CSWGuiLabel        m_lblBg;
#endif

    // The level-up steps (BTN_STEPNAME1-5), the index into m_aPages, m_aLabels, m_aButtons and
    // m_anState.
    enum {
        LEVELUP_STEP_ABILITIES = 0,
        LEVELUP_STEP_SKILLS = 1,
        LEVELUP_STEP_FEATS = 2,
        LEVELUP_STEP_POWERS = 3,
        LEVELUP_STEP_ACCEPT = 4,
    };
    CSWGuiLabelHilight m_aPages[5];
    CSWGuiLabel        m_aLabels[5];
    CSWGuiButton       m_aButtons[5];
    CSWGuiButton       m_btnBack;
    CSWGuiButton       m_btnCancel;

    int  m_nCurrentPage;
    int  m_nFirstPage;
    // One flag per page; 1 means the page is selectable.
    int  m_anState[5];
    int  m_bCanCancel;
    int  m_bHasGrantedFeats;
    int  m_bHasGrantedPowers;
};

#if !KOTOR1  // K1's GUI base classes are smaller
K2_LAYOUT_ASSERT(sizeof(CSWGuiLevelUpPanel) == 0x25b8, "CSWGuiLevelUpPanel size drift");
#endif
